function convertToBase7(num) {
  if (num === 0) {
    return '0';
  }
  const negative = num < 0;
  let value = Math.abs(num);
  let digits = '';
  while (value > 0) {
    const digit = value % 7;
    digits = digit + digits;
    value = Math.floor(value / 7);
  }
  return negative ? '-' + digits : digits;
}

