function convertToBase7(num) {
  // Find the largest power of 7 that fits, then count how many times each power can be subtracted.
  let rest = num < 0 ? -num : num;
  let power = 1;
  while (power * 7 <= rest) power *= 7;
  let out = '';
  for (; power >= 1; power /= 7) {
    let count = 0;
    while (rest >= power) { rest -= power; count++; }
    out += String(count);
  }
  return (num < 0 ? '-' : '') + out;
}

